class Solution {
public:
    int superPow(int a, vector<int>& b) {
        const int MOD = 1337;
        auto powMod = [&](long long base, int exp) {
            long long res = 1;
            base %= MOD;
            while (exp > 0) {
                if (exp % 2 == 1) res = (res * base) % MOD;
                base = (base * base) % MOD;
                exp /= 2;
            }
            return res;
        };
        long long res = 1;
        for (int digit : b) {
            res = (powMod(res, 10) * powMod(a, digit)) % MOD;
        }
        return (int)res;
    }
};

class Solution {
    private static final int MOD = 1337;

    public int superPow(int a, int[] b) {
        long res = 1;
        for (int digit : b) {
            res = (powMod(res, 10) * powMod(a, digit)) % MOD;
        }
        return (int) res;
    }

    private long powMod(long base, int exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return res;
    }
}

var superPow = function(a, b) {
    const MOD = 1337;
    const powMod = (base, exp) => {
        let res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 === 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp = Math.floor(exp / 2);
        }
        return res;
    };
    let res = 1;
    for (const digit of b) {
        res = (powMod(res, 10) * powMod(a, digit)) % MOD;
    }
    return res;
};
